        clearInterval(timerInterval);
        timerElement.textContent = "00:00 EXPIRED";
        timerElement.classList.remove('text-[#14452f]');
        timerElement.classList.add('text-error');
      } else {
        timeLeft--;
        const minutes = Math.floor(timeLeft / 60);
        const seconds = timeLeft % 60;
        timerElement.textContent = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
      }
    }, 1000);
  }

  // Toggle Password Visibility
  function togglePasswordVisibility(fieldId, iconId) {
    const field = document.getElementById(fieldId);
    const icon = document.getElementById(iconId);
    if (field && icon) {
      if (field.type === 'password') {
        field.type = 'text';
        icon.textContent = 'visibility_off';
      } else {
        field.type = 'password';
        icon.textContent = 'visibility';
      }
    }
  }

  // Real-time evaluation stub for password strength
  function evaluateStrength(val) {
    const label = document.getElementById('strength-label');
    if (!label) return;
    if (val.length < 8) {
      label.textContent = "Vulnerable (< 8 chars)";
      label.className = "text-error font-bold uppercase tracking-wider";
    } else if (val.length < 12) {
      label.textContent = "Adequate (Stage 2 Requires 12+)";
      label.className = "text-[#eabf55] font-bold uppercase tracking-wider";
    } else {
      label.textContent = "Cryptographically Strong (100%)";
      label.className = "text-[#14452f] font-bold uppercase tracking-wider";
    }
  }

  // Handle Password Reset Submission
  function handlePasswordReset() {
    const btn = document.getElementById('submitButton');
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = `
        <span class="flex h-3 w-3 rounded-full bg-primary-fixed animate-ping mr-2"></span>
        <span>Re-deriving clearance cryptographic hash...</span>
      `;
      setTimeout(() => {
        btn.innerHTML = `
          <span class="material-symbols-outlined text-[20px] text-primary-fixed">check_circle</span>
          <span>Clearance Pass Updated Successfully</span>
        `;
        btn.classList.remove('bg-[#173153]', 'hover:bg-[#1f3f69]');
        btn.classList.add('bg-[#14452f]');
      }, 1200);
    }
  }
</script></main><footer class="w-full bg-surface-container-lowest px-space-lg py-space-md flex flex-col md:flex-row items-center justify-between gap-space-sm"><div class="flex items-center gap-space-xs font-label-sm text-label-sm text-outline"><span class="material-symbols-outlined text-[16px] text-primary">verified</span><span>Cavite State University • Confidential Document Verification &amp; Clearance Gateway • RA 10173 Compliant</span></div><div class="font-label-sm text-label-sm text-outline-variant">ISO/IEC 27001 AUDITED INFRASTRUCTURE</div></footer>
